#include "stdlib/blas/ext/base/dcross.h"
#include <stdio.h>

int main( void ) {
	// Create strided input arrays:
	const double x[] = { 1.0, 2.0, 3.0 };
	const double y[] = { 4.0, 5.0, 6.0 };

	// Create an output array:
	double z[] = { 0.0, 0.0, 0.0 };

	// Specify strides:
	const int strideX = 1;
	const int strideY = 1;
	const int strideZ = 1;

	// Compute the cross product:
	stdlib_strided_dcross( x, strideX, y, strideY, z, strideZ );

	// Print the result:
	for ( int i = 0; i < 3; i++ ) {
		printf( "z[ %i ] = %lf\n", i, z[ i ] );
	}
}
